<script setup lang="ts">import AppLayout from '@/Layouts/AppLayout.vue'; import EmptyState from '@/Components/EmptyState.vue'; import { Link } from '@inertiajs/vue3'; import type { Order } from '@/types'; defineProps<{ orders: { data: Order[] } }>();</script><template><AppLayout><div class="mb-6 flex items-center justify-between"><h1 class="text-2xl font-black">Orders</h1><Link :href="route('orders.create')" class="btn-primary">Create order</Link></div><div v-if="orders.data.length" class="overflow-hidden rounded-3xl border border-white/10"><table class="w-full text-left text-sm"><thead class="bg-white/10 text-slate-300"><tr><th class="p-4">Code</th><th>Title</th><th>Status</th><th>Priority</th><th>Deadline</th></tr></thead><tbody><tr v-for="order in orders.data" :key="order.id" class="border-t border-white/10"><td class="p-4"><Link :href="route('orders.show', order.id)" class="text-cyan-300">{{ order.orderCode }}</Link></td><td>{{ order.title }}</td><td>{{ order.status }}</td><td>{{ order.priority }}</td><td>{{ new Date(order.deadline).toLocaleDateString() }}</td></tr></tbody></table></div><EmptyState v-else title="No orders yet" description="Create your first outsourced task order." /></AppLayout></template>
